{"path": "/app/ars.R", "content": "ars_validate_inputs <- function(n, f, domain, x_init, is_log, dlogf, max_iter) {
  if (!is.numeric(n) || length(n) != 1 || is.na(n) || n <= 0 || n != as.integer(n)) {
    stop("n must be a positive integer.")
  }
  if (!is.function(f)) {
    stop("f must be a function that evaluates the density.")
  }
  if (length(domain) != 2 || any(is.na(domain)) || !is.numeric(domain) || domain[1] >= domain[2]) {
    stop("domain must be a numeric vector of length 2 with lower < upper.")
  }
  if (!is.logical(is_log) || length(is_log) != 1) {
    stop("is_log must be TRUE or FALSE.")
  }
  if (!is.null(dlogf) && !is.function(dlogf)) {
    stop("dlogf must be a function returning the derivative of the log-density.")
  }
  if (!is.null(x_init)) {
    if (!is.numeric(x_init) || length(x_init) < 2) {
      stop("x_init must be a numeric vector of length >= 2.")
    }
    if (any(x_init <= domain[1]) || any(x_init >= domain[2])) {
      stop("x_init values must lie strictly inside the domain.")
    }
  }
  if (!is.numeric(max_iter) || length(max_iter) != 1 || max_iter <= 0) {
    stop("max_iter must be a positive integer.")
  }
  invisible(TRUE)
}

ars_make_logpdf <- function(f, is_log, ...) {
  if (is_log) {
    function(x) {
      val <- f(x, ...)
      if (!is.numeric(val)) {
        stop("Density function must return numeric values.")
      }
      as.numeric(val)
    }
  } else {
    function(x) {
      val <- f(x, ...)
      if (!is.numeric(val)) {
        stop("Density function must return numeric values.")
      }
      val <- as.numeric(val)
      if (any(val < 0, na.rm = TRUE)) {
        stop("Density function returned negative values.")
      }
      log_val <- rep(-Inf, length(val))
      ok <- is.finite(val) & val > 0
      log_val[ok] <- log(val[ok])
      log_val
    }
  }
}

ars_eval_logpdf <- function(logpdf, x) {
  val <- logpdf(x)
  if (!is.numeric(val)) {
    stop("Density evaluation must return numeric values.")
  }
  if (length(val) != length(x)) {
    stop("Density function must be vectorized and return output of same length as input.")
  }
  as.numeric(val)
}

ars_eval_dlogpdf <- function(dlogpdf, x) {
  val <- dlogpdf(x)
  if (!is.numeric(val)) {
    stop("Derivative evaluation must return numeric values.")
  }
  if (length(val) != length(x)) {
    stop("Derivative function must be vectorized and return output of same length as input.")
  }
  as.numeric(val)
}

ars_numeric_dlogpdf <- function(logpdf, domain, eps = 1e-6) {
  function(x) {
    x <- as.numeric(x)
    h <- eps * (1 + abs(x))
    x_plus <- x + h
    x_minus <- x - h
    if (is.finite(domain[2])) {
      x_plus <- pmin(x_plus, domain[2] - 1e-10)
    }
    if (is.finite(domain[1])) {
      x_minus <- pmax(x_minus, domain[1] + 1e-10)
    }
    log_plus <- logpdf(x_plus)
    log_minus <- logpdf(x_minus)
    log_x <- logpdf(x)
    deriv <- numeric(length(x))
    for (i in seq_along(x)) {
      if (x_plus[i] == x[i]) {
        deriv[i] <- (log_x[i] - log_minus[i]) / (x[i] - x_minus[i])
      } else if (x_minus[i] == x[i]) {
        deriv[i] <- (log_plus[i] - log_x[i]) / (x_plus[i] - x[i])
      } else {
        deriv[i] <- (log_plus[i] - log_minus[i]) / (x_plus[i] - x_minus[i])
      }
    }
    deriv
  }
}

ars_find_initial_points <- function(domain, logpdf, n = 3, max_attempts = 1000) {
  pts <- numeric(0)
  attempt <- 0
  while (length(pts) < n && attempt < max_attempts) {
    candidate <- if (all(is.finite(domain))) {
      runif(1, domain[1], domain[2])
    } else if (is.finite(domain[1]) && !is.finite(domain[2])) {
      domain[1] + rexp(1)
    } else if (!is.finite(domain[1]) && is.finite(domain[2])) {
      domain[2] - rexp(1)
    } else {
      rnorm(1)
    }
    val <- logpdf(candidate)
    if (is.finite(val)) {
      pts <- unique(c(pts, candidate))
    }
    attempt <- attempt + 1
  }
  if (length(pts) < n) {
    stop("Unable to find enough initial points with finite log-density.")
  }
  sort(pts)[1:n]
}

ars_check_log_concavity <- function(x, hprime, tol = 1e-8) {
  if (length(hprime) > 1 && any(diff(hprime) > tol)) {
    stop("Non-log-concave density detected: derivative is not non-increasing.")
  }
  invisible(TRUE)
}

ars_prune_support <- function(x, h, hprime, tol = 1e-8) {
  repeat {
    if (length(x) <= 1) break
    c_val <- h - hprime * x
    diff_slopes <- abs(diff(hprime)) < tol
    if (!any(diff_slopes)) break
    idx <- which(diff_slopes)[1]
    if (abs(c_val[idx] - c_val[idx + 1]) < tol) {
      x <- x[-(idx + 1)]
      h <- h[-(idx + 1)]
      hprime <- hprime[-(idx + 1)]
    } else {
      stop("Non-log-concave density detected: parallel tangents with different intercepts.")
    }
  }
  list(x = x, h = h, hprime = hprime)
}

ars_log_diff_exp <- function(a, b) {
  if (b > a) {
    stop("Invalid arguments to ars_log_diff_exp: b must be <= a.")
  }
  a + log1p(-exp(b - a))
}

ars_log_sum_exp <- function(log_vals) {
  m <- max(log_vals)
  m + log(sum(exp(log_vals - m)))
}

ars_log_integral_segment <- function(c, s, zL, zR) {
  if (s == 0) {
    if (!is.finite(zL) || !is.finite(zR)) {
      stop("Non-integrable envelope segment with zero slope and infinite bounds.")
    }
    if (zR <= zL) {
      stop("Invalid envelope segment bounds.")
    }
    return(c + log(zR - zL))
  }
  if (is.infinite(zL) && s <= 0) {
    stop("Non-integrable envelope: left tail slope must be positive.")
  }
  if (is.infinite(zR) && s >= 0) {
    stop("Non-integrable envelope: right tail slope must be negative.")
  }
  if (is.infinite(zL)) {
    return(c - log(s) + s * zR)
  }
  if (is.infinite(zR)) {
    return(c - log(-s) + s * zL)
  }
  a <- s * zR
  b <- s * zL
  if (s > 0) {
    log_diff <- ars_log_diff_exp(a, b)
  } else {
    log_diff <- ars_log_diff_exp(b, a)
  }
  c - log(abs(s)) + log_diff
}

ars_compute_intersections <- function(x, h, hprime, domain, tol = 1e-8) {
  m <- length(x)
  if (m == 1) {
    return(c(domain[1], domain[2]))
  }
  z <- numeric(m + 1)
  z[1] <- domain[1]
  z[m + 1] <- domain[2]
  for (i in 1:(m - 1)) {
    denom <- hprime[i] - hprime[i + 1]
    if (denom <= tol) {
      stop("Non-log-concave density detected: derivative is not strictly decreasing.")
    }
    z[i + 1] <- (h[i + 1] - h[i] - x[i + 1] * hprime[i + 1] + x[i] * hprime[i]) / denom
    if (z[i + 1] <= x[i] + tol || z[i + 1] >= x[i + 1] - tol) {
      stop("Non-log-concave density detected: tangent intersections not between support points.")
    }
  }
  if (any(diff(z) <= 0)) {
    stop("Non-log-concave density detected: tangent intersections not ordered.")
  }
  z
}

ars_build_envelope <- function(x, h, hprime, domain) {
  z <- ars_compute_intersections(x, h, hprime, domain)
  c_val <- h - hprime * x
  s_val <- hprime
  log_w <- numeric(length(x))
  for (i in seq_along(x)) {
    log_w[i] <- ars_log_integral_segment(c_val[i], s_val[i], z[i], z[i + 1])
  }
  log_total <- ars_log_sum_exp(log_w)
  weights <- exp(log_w - log_total)
  list(x = x, h = h, hprime = hprime, z = z, c = c_val, s = s_val, log_w = log_w, weights = weights)
}

ars_sample_segment <- function(s, zL, zR) {
  u <- runif(1)
  if (s == 0) {
    if (!is.finite(zL) || !is.finite(zR)) {
      stop("Cannot sample from flat segment with infinite bounds.")
    }
    return(zL + u * (zR - zL))
  }
  if (is.infinite(zL)) {
    return((log(u) + s * zR) / s)
  }
  if (is.infinite(zR)) {
    return((log1p(-u) + s * zL) / s)
  }
  logA <- s * zL
  logB <- s * zR
  delta <- logB - logA
  if (delta > 50) {
    log_val <- log(u) + delta
  } else if (delta < -50) {
    log_val <- log1p(-u)
  } else {
    log_val <- log1p(u * (exp(delta) - 1))
  }
  (logA + log_val) / s
}

ars_sample_from_envelope <- function(env) {
  idx <- sample(seq_along(env$weights), size = 1, prob = env$weights)
  x <- ars_sample_segment(env$s[idx], env$z[idx], env$z[idx + 1])
  list(x = x, idx = idx)
}

ars_upper_hull <- function(x, env) {
  idx <- findInterval(x, env$z, rightmost.closed = TRUE, all.inside = TRUE)
  env$h[idx] + env$hprime[idx] * (x - env$x[idx])
}

ars_lower_hull <- function(x, x_supp, h_supp) {
  if (length(x_supp) < 2) {
    return(-Inf)
  }
  if (x <= x_supp[1] || x >= x_supp[length(x_supp)]) {
    return(-Inf)
  }
  idx <- findInterval(x, x_supp, rightmost.closed = TRUE)
  x1 <- x_supp[idx]
  x2 <- x_supp[idx + 1]
  h1 <- h_supp[idx]
  h2 <- h_supp[idx + 1]
  h1 + (h2 - h1) * (x - x1) / (x2 - x1)
}

ars_add_support <- function(x, h, hprime, x_new, h_new, hprime_new, tol = 1e-10) {
  if (any(abs(x_new - x) < tol)) {
    return(list(x = x, h = h, hprime = hprime, added = FALSE))
  }
  x <- c(x, x_new)
  h <- c(h, h_new)
  hprime <- c(hprime, hprime_new)
  ord <- order(x)
  list(x = x[ord], h = h[ord], hprime = hprime[ord], added = TRUE)
}

ars <- function(n, f, dlogf = NULL, domain = c(-Inf, Inf), x_init = NULL,
                is_log = FALSE, max_iter = 100000, ...) {
  ars_validate_inputs(n, f, domain, x_init, is_log, dlogf, max_iter)

  logpdf <- ars_make_logpdf(f, is_log, ...)
  dlogpdf <- if (is.null(dlogf)) {
    ars_numeric_dlogpdf(logpdf, domain)
  } else {
    function(x) dlogf(x, ...)
  }

  x_test <- if (all(is.finite(domain))) {
    seq(domain[1], domain[2], length.out = 3)
  } else if (is.finite(domain[1]) && !is.finite(domain[2])) {
    domain[1] + c(0.5, 1, 2)
  } else if (!is.finite(domain[1]) && is.finite(domain[2])) {
    domain[2] - c(2, 1, 0.5)
  } else {
    c(-1, 0, 1)
  }
  ars_eval_logpdf(logpdf, x_test)

  if (is.null(x_init)) {
    x_init <- ars_find_initial_points(domain, logpdf)
  }

  x <- sort(unique(x_init))
  h <- ars_eval_logpdf(logpdf, x)
  if (any(!is.finite(h))) {
    stop("Initial points have non-finite log-density values.")
  }
  hprime <- ars_eval_dlogpdf(dlogpdf, x)
  if (any(!is.finite(hprime))) {
    stop("Initial points have non-finite derivatives.")
  }

  support <- ars_prune_support(x, h, hprime)
  x <- support$x
  h <- support$h
  hprime <- support$hprime

  ars_check_log_concavity(x, hprime)

  samples <- numeric(n)
  accepted <- 0
  iterations <- 0

  while (accepted < n) {
    iterations <- iterations + 1
    if (iterations > max_iter) {
      stop("Maximum iterations exceeded in ARS. Check target density or increase max_iter.")
    }

    env <- ars_build_envelope(x, h, hprime, domain)
    draw <- ars_sample_from_envelope(env)
    candidate <- draw$x

    if (candidate <= domain[1] || candidate >= domain[2]) {
      next
    }

    ux <- ars_upper_hull(candidate, env)
    lx <- ars_lower_hull(candidate, x, h)

    if (log(runif(1)) <= lx - ux) {
      accepted <- accepted + 1
      samples[accepted] <- candidate
    } else {
      hx <- ars_eval_logpdf(logpdf, candidate)
      if (!is.finite(hx)) {
        next
      }
      if (log(runif(1)) <= hx - ux) {
        accepted <- accepted + 1
        samples[accepted] <- candidate
      }

      hprime_new <- ars_eval_dlogpdf(dlogpdf, candidate)
      if (is.finite(hprime_new)) {
        added <- ars_add_support(x, h, hprime, candidate, hx, hprime_new)
        x <- added$x
        h <- added$h
        hprime <- added$hprime
        support <- ars_prune_support(x, h, hprime)
        x <- support$x
        h <- support$h
        hprime <- support$hprime
        ars_check_log_concavity(x, hprime)
      }
    }
  }

  samples
}

report_test <- function(name, pass, mean_val, sd_val) {
  status <- if (pass) "PASS" else "FAIL"
  cat(sprintf("%s: %s (mean=%.6f, sd=%.6f)\n", name, status, mean_val, sd_val))
}

test <- function() {
  set.seed(123)

  logpdf_normal <- function(x) dnorm(x, log = TRUE)
  dlog_numeric <- ars_numeric_dlogpdf(logpdf_normal, c(-Inf, Inf))
  points <- seq(-2, 2, length.out = 9)
  approx <- dlog_numeric(points)
  truth <- -points
  abs_err <- abs(approx - truth)
  mean_err <- mean(abs_err)
  sd_err <- sd(abs_err)
  pass <- mean_err < 1e-3
  report_test("NumericDerivativeNormal", pass, mean_err, sd_err)

  normal_samples <- ars(
    n = 5000,
    f = dnorm,
    dlogf = function(x) -x,
    is_log = FALSE,
    domain = c(-Inf, Inf),
    x_init = c(-2, 0, 2)
  )
  mean_norm <- mean(normal_samples)
  sd_norm <- sd(normal_samples)
  pass_norm <- abs(mean_norm) < 0.05 && abs(sd_norm - 1) < 0.05
  report_test("ARS_Normal", pass_norm, mean_norm, sd_norm)
  writeLines(format(normal_samples, digits = 6), "/app/normal_samples.txt")

  rate <- 2
  exp_density <- function(x) {
    ifelse(x < 0, 0, rate * exp(-rate * x))
  }
  exp_dlog <- function(x) {
    ifelse(x < 0, NA, -rate)
  }
  exp_samples <- ars(
    n = 5000,
    f = exp_density,
    dlogf = exp_dlog,
    is_log = FALSE,
    domain = c(0, Inf),
    x_init = c(0.2, 0.8, 1.5)
  )
  mean_exp <- mean(exp_samples)
  sd_exp <- sd(exp_samples)
  pass_exp <- abs(mean_exp - 1 / rate) < 0.05 && abs(sd_exp - 1 / rate) < 0.05
  report_test("ARS_Exponential", pass_exp, mean_exp, sd_exp)
  writeLines(format(exp_samples, digits = 6), "/app/exponential_samples.txt")

  nonconcave <- function(x) exp(sin(x))
  dlog_non <- function(x) cos(x)
  x_init_nc <- seq(0.5, 5.5, length.out = 4)
  mean_stat <- mean(dlog_non(x_init_nc))
  sd_stat <- sd(dlog_non(x_init_nc))
  pass_nc <- FALSE
  tryCatch({
    ars(
      n = 100,
      f = nonconcave,
      dlogf = dlog_non,
      is_log = FALSE,
      domain = c(0, 2 * pi),
      x_init = x_init_nc
    )
    pass_nc <- FALSE
  }, error = function(e) {
    pass_nc <<- TRUE
  })
  report_test("NonLogConcaveCheck", pass_nc, mean_stat, sd_stat)

  invisible(list(normal = normal_samples, exponential = exp_samples))
}
